#!/usr/bin/env python3
"""Instala Vera con 3 BD: SQL + Neo4j + Chroma."""
import os, base64, shutil
from datetime import datetime

VORTU = os.path.expanduser('~/Desktop/vortu/backend')
VERA_DIR = os.path.join(VORTU, 'vera')
API_DIR = os.path.join(VORTU, 'api')

if not os.path.exists(VERA_DIR):
    print("ERROR: vera/ no existe"); exit(1)

ts = datetime.now().strftime('%H%M%S')

# Backup y crear vera/context.py
ctx_path = os.path.join(VERA_DIR, 'context.py')
if os.path.exists(ctx_path):
    shutil.copy(ctx_path, ctx_path + '.bak_' + ts)
    print(f"~ backup vera/context.py")
with open(ctx_path, 'wb') as f:
    f.write(base64.b64decode(""))
print(f"+ vera/context.py (constructor multi-BD)")

# Backup y actualizar api/vera_v2.py
api_path = os.path.join(API_DIR, 'vera_v2.py')
if os.path.exists(api_path):
    shutil.copy(api_path, api_path + '.bak_' + ts)
    print(f"~ backup api/vera_v2.py")
with open(api_path, 'wb') as f:
    f.write(base64.b64decode(""))
print(f"+ api/vera_v2.py (usa 3 BD + Chroma)")

print()
print("OK. Reinicia uvicorn y prueba:")
print('  TOKEN="..." curl -s "http://localhost:8000/api/vera/v2/conversations" -X POST -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d \'{}\' ')
